import React, { Component } from "react";
import "./Homepage.css";


export default class Homepage extends Component {

    constructor(props) {
        super(props);
        this.state = {
        homepage: null,
        };
    }

    componentDidMount() {
        const pageName = "Homepage";
        fetch(`http://localhost:3001/${pageName}`) 
            .then(response => response.json())
            .then(page => {
                this.setState({ homepage: page });
            })
            .catch(error => console.error('Error fetching data:', error));
    }

    render() {
        const { homepage } = this.state;
        if (!homepage) return <div>PAGE NOT FOUND</div>;
        const contentHome = homepage.content;
        return (
            <div className="containersq">
                <div>
             <section className="boxcon">
            <div classNmae="slider">
            <img  id="slide-1" src="HomePage1.png" alt="Your"/>
            <img  id="slide-2" src="HomePage2.png" alt="Your"/>              
            <img  id="slide-3" src="HomePage3.png" alt="Your"/>
            <div className="slider-nav"> 
            <a herf="#slide-1"></a>
            <a herf="#slide-3"></a>
            <a herf="#slide-3"></a>

            </div>
            </div>
            </section>
                </div>
                <div className="sentence1">
                     {contentHome.map((item) => (
                    <p>
                        {item.t1}
                    </p>
                        ))}
                </div>
                <div className="sentence2">
                {contentHome.map((item) => (
                    <p>
                        {item.t2}
                    </p>
                        ))}
                </div>



                <a className="findmypet" href="/Service">Find my pet</a>
                <div className="squares-container">
                <div className="square">Rescue</div>
                <div className="square">Shelters</div>
                <div className="square">Find a pet</div>
                <div className="square">Help us</div>
            </div>

            </div>
        );
    }
}
